// First node MUST verify the bearer credential (same discipline as the
// jobs webhooks). The value lives in the LXC env (/etc/n8n/n8n.env) as
// ALERTS_WEBHOOK_SECRET, never in this JSON. Alertmanager presents it as
// an Authorization: Bearer header (credentials_file in its config).
const req = $input.first().json;
const secret = $env.ALERTS_WEBHOOK_SECRET;
const presented = (req.headers || {})['authorization'];
if (!secret || presented !== `Bearer ${secret}`) {
  // ok:false routes to the 401 responder — Alertmanager must SEE the
  // failure (2xx would be a silent black hole during rotation skew).
  return [{ json: { ok: false, error: 'unauthorized' } }];
}
const body = req.body || {};
// Alertmanager webhook payload: {status, groupLabels, alerts: [...]}.
// Caps bound attacker-controllable strings (any pod can reach the
// unauthenticated Alertmanager API and inject alert text — see runbook).
const clip = (s, n) => String(s ?? '').replace(/[\r\n]+/g, ' ').slice(0, n);
const alerts = (body.alerts || []).slice(0, 20).map((a) => ({
  status: clip(a.status, 16),
  alertname: clip(a.labels?.alertname, 120) || 'unknown',
  namespace: clip(a.labels?.namespace, 80),
  severity: clip(a.labels?.severity, 24),
  summary: clip(a.annotations?.summary, 500),
  since: clip(a.startsAt, 40),
}));
const headline = alerts
  .map((a) => `[${a.status.toUpperCase()}] ${a.alertname}${a.namespace ? ` (${a.namespace})` : ''}: ${a.summary}`)
  .join('\n');
return [{ json: { ok: true, group_status: clip(body.status, 16), headline, alerts } }];
